#!/usr/bin/env python3
"""Biomedical Research Landscape 2024–2026 — Analysis & Report Generator"""

import pandas as pd
import numpy as np
import json
import os
from collections import Counter
from io import StringIO
import base64

# ── Load data ──────────────────────────────────────────────────────────
DATA = "/app/benchmark/data.csv"
df = pd.read_csv(DATA, dtype=str, keep_default_na=False)
print(f"Loaded {len(df)} records, {len(df.columns)} columns")

# Convert numeric columns
df["pub_year"] = pd.to_numeric(df["pub_year"], errors="coerce")
df["pub_month_num"] = pd.to_numeric(df["pub_month_num"], errors="coerce")
df["authors_count"] = pd.to_numeric(df["authors_count"], errors="coerce")
df["open_access"] = df["open_access"].map({"True": True, "False": False})

# ── Compute KPIs ───────────────────────────────────────────────────────

# KPI 1: Total Publications by year
year_counts = df["pub_year"].value_counts().sort_index()
total_pubs = len(df)
print(f"\n=== Total Publications: {total_pubs} ===")
for yr, cnt in year_counts.items():
    print(f"  {yr}: {cnt} ({100*cnt/total_pubs:.1f}%)")

# KPI 2: Open Access Rate over time
oa_rate = df["open_access"].mean() * 100
print(f"\nOpen Access Rate: {oa_rate:.1f}%")

# Monthly OA rate
df["year_month"] = df.apply(lambda r: f"{int(r['pub_year'])}-{int(r['pub_month_num']):02d}"
                            if r["pub_month_num"] > 0 else f"{int(r['pub_year'])}-Unknown", axis=1)

# Filter only known months for monthly analysis
df_known_month = df[df["pub_month_num"] > 0].copy()

monthly_oa = df_known_month.groupby("year_month").agg(
    total=("open_access", "count"),
    oa_count=("open_access", "sum"),
    oa_rate=("open_access", "mean")
).reset_index()
monthly_oa["oa_rate_pct"] = monthly_oa["oa_rate"] * 100

# KPI 3: Median authors
median_authors = df["authors_count"].median()
print(f"\nMedian Authors per Publication: {median_authors}")

median_authors_by_year = df.groupby("pub_year")["authors_count"].median()
print(f"Median authors by year: {median_authors_by_year.to_dict()}")

# KPI 4: Top 10 Countries Share
country_counts = df["country"].value_counts()
top10_countries = country_counts.head(10)
top10_share = top10_countries.sum() / total_pubs * 100
print(f"\nTop 10 Countries Share: {top10_share:.1f}%")
for c, cnt in top10_countries.items():
    print(f"  {c}: {cnt} ({100*cnt/total_pubs:.1f}%)")

# KPI 5: Emerging Topic Growth Rate (month-over-month for major_topic)
# First, aggregate major topics by month
topic_monthly = df_known_month.groupby(["major_topic", "year_month"]).size().reset_index(name="count")
topic_monthly = topic_monthly[topic_monthly["major_topic"] != ""]

# Get top topics by total volume
top_topics = df[df["major_topic"] != ""]["major_topic"].value_counts().head(20)
print(f"\n=== Top 20 Major Topics ===")
for t, cnt in top_topics.items():
    print(f"  {t}: {cnt}")

# Compute month-over-month growth for top topics
def compute_mom_growth(topic_df):
    """Compute average MoM growth rate for a topic"""
    topic_df = topic_df.sort_values("year_month")
    if len(topic_df) < 2:
        return 0
    growth_rates = []
    for i in range(1, len(topic_df)):
        prev = topic_df.iloc[i-1]["count"]
        curr = topic_df.iloc[i]["count"]
        if prev > 0:
            growth_rates.append((curr - prev) / prev * 100)
    return np.mean(growth_rates) if growth_rates else 0

topic_growth = {}
for topic in top_topics.index[:20]:
    tdf = topic_monthly[topic_monthly["major_topic"] == topic]
    growth = compute_mom_growth(tdf)
    topic_growth[topic] = growth

# Sort by growth rate
sorted_growth = sorted(topic_growth.items(), key=lambda x: x[1], reverse=True)
print(f"\n=== Topic Growth Rates (avg MoM %) ===")
for t, g in sorted_growth:
    print(f"  {t}: {g:+.1f}%")

# ── Additional Analysis ────────────────────────────────────────────────

# Monthly publication volume
monthly_pubs = df_known_month.groupby("year_month").size().reset_index(name="count")

# Research type distribution
# split multi-value research_type
all_types = []
for rt in df["research_type"]:
    types = [t.strip() for t in rt.split(";")]
    all_types.extend(types)
research_type_counts = Counter(all_types)
print(f"\n=== Research Types ===")
for rt, cnt in research_type_counts.most_common():
    print(f"  {rt}: {cnt}")

# Authors per country
country_median_authors = df.groupby("country")["authors_count"].median()
# top 15 by volume, get median authors
top15_countries = country_counts.head(15).index
country_author_data = {c: df[df["country"]==c]["authors_count"].median() for c in top15_countries}

# OA by country (top 15)
country_oa = {}
for c in top15_countries:
    cdf = df[df["country"] == c]
    country_oa[c] = cdf["open_access"].mean() * 100

# OA by research type
oa_by_type = {}
for rt in ["Journal Article", "Review", "Systematic Review", "Case Report"]:
    mask = df["research_type"].str.contains(rt, na=False)
    oa_by_type[rt] = df[mask]["open_access"].mean() * 100

# Research type over time
type_yearly = {}
for rt in ["Journal Article", "Review", "Case Report", "Systematic Review"]:
    type_yearly[rt] = {}
    for yr in [2024, 2025, 2026]:
        yr_mask = (df["pub_year"] == yr) & df["research_type"].str.contains(rt, na=False)
        type_yearly[rt][yr] = yr_mask.sum()

# Yearly summary
yearly_data = {}
for yr in [2024, 2025, 2026]:
    yr_df = df[df["pub_year"] == yr]
    yearly_data[yr] = {
        "count": len(yr_df),
        "oa_rate": yr_df["open_access"].mean() * 100,
        "median_authors": yr_df["authors_count"].median(),
        "pct_total": len(yr_df) / total_pubs * 100
    }

# Monthly volume by year
monthly_vol_2024 = df_known_month[df_known_month["pub_year"] == 2024].groupby("pub_month_num").size()
monthly_vol_2025 = df_known_month[df_known_month["pub_year"] == 2025].groupby("pub_month_num").size()
monthly_vol_2026 = df_known_month[df_known_month["pub_year"] == 2026].groupby("pub_month_num").size()

# ── Save analysis results ──────────────────────────────────────────────
analysis = {
    "total_pubs": total_pubs,
    "year_counts": {int(k): int(v) for k, v in year_counts.items()},
    "oa_rate": round(oa_rate, 1),
    "median_authors": float(median_authors),
    "top10_share": round(top10_share, 1),
    "top10_countries": [(str(c), int(cnt)) for c, cnt in top10_countries.items()],
    "top_topics": [(str(t), int(cnt)) for t, cnt in top_topics.head(20).items()],
    "topic_growth": {str(k): round(v, 1) for k, v in sorted_growth[:15]},
    "research_types": research_type_counts.most_common(),
    "yearly_data": {int(k): v for k, v in yearly_data.items()},
    "oa_by_type": {k: round(v, 1) for k, v in oa_by_type.items()},
    "country_oa": {str(k): round(v, 1) for k, v in country_oa.items()},
    "country_median_authors": {str(k): round(v, 1) for k, v in country_author_data.items()},
}

with open("/app/output/analysis.json", "w") as f:
    json.dump(analysis, f, indent=2)
print("\nAnalysis saved to /app/output/analysis.json")

# ── Prepare data series for charts ─────────────────────────────────────
# Monthly volume series
months_order = []
for yr in [2024, 2025, 2026]:
    for m in range(1, 13):
        months_order.append(f"{yr}-{m:02d}")

monthly_series = [int(monthly_pubs[monthly_pubs["year_month"]==m]["count"].values[0])
                  if m in monthly_pubs["year_month"].values else 0
                  for m in months_order]

monthly_oa_series = [float(monthly_oa[monthly_oa["year_month"]==m]["oa_rate_pct"].values[0])
                     if m in monthly_oa["year_month"].values else None
                     for m in months_order]

# Write monthly data for chart JS
monthly_labels = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
chart_data = {
    "months_order": months_order,
    "monthly_labels_full": months_order,
    "monthly_volumes": monthly_series,
    "monthly_oa_rates": monthly_oa_series
}

# ────────────────────────────────────────────────────────────────────────
# BUILD THE HTML REPORT
# ────────────────────────────────────────────────────────────────────────
# We'll use Chart.js CDN for interactive charts and a clean, professional layout.

def fmt(n, decimals=0):
    """Format numbers for display"""
    if decimals == 0:
        return f"{int(n):,}"
    return f"{n:,.{decimals}f}"

def pct(n):
    return f"{n:.1f}%"

# Build chart data structures as JSON for embedding
monthly_volumes_json = json.dumps(monthly_series)
monthly_labels_json = json.dumps(months_order)
monthly_oa_json = json.dumps([v if v is not None else None for v in monthly_oa_series])

# Country chart data
country_names = [str(c) for c, _ in top10_countries.items()]
country_vals = [int(cnt) for _, cnt in top10_countries.items()]
country_names_json = json.dumps(country_names)
country_vals_json = json.dumps(country_vals)

# Topic chart data
topic_names = [str(t) for t, _ in top_topics.head(15).items()]
topic_vals = [int(cnt) for _, cnt in top_topics.head(15).items()]
topic_names_json = json.dumps(topic_names)
topic_vals_json = json.dumps(topic_vals)

# Topic growth data
growth_names = [str(t) for t, _ in sorted_growth[:12]]
growth_vals = [round(v, 1) for _, v in sorted_growth[:12]]
growth_names_json = json.dumps(growth_names)
growth_vals_json = json.dumps(growth_vals)

# Research types
rt_names = [rt for rt, _ in research_type_counts.most_common(8)]
rt_vals = [cnt for _, cnt in research_type_counts.most_common(8)]
rt_names_json = json.dumps(rt_names)
rt_vals_json = json.dumps(rt_vals)

# OA by type
oat_names = list(oa_by_type.keys()) + ["Overall"]
oat_vals = [v for v in oa_by_type.values()] + [oa_rate]
oat_names_json = json.dumps(oat_names)
oat_vals_json = json.dumps(oat_vals)

# Country OA
coa_names_json = json.dumps([str(c) for c, _ in top10_countries.items()])
coa_vals_json = json.dumps([round(country_oa.get(str(c), 0), 1) for c, _ in top10_countries.items()])

# Median authors by country
mac_names_json = json.dumps([str(c) for c, _ in top10_countries.items()])
mac_vals_json = json.dumps([round(country_median_authors.get(c, 0), 1) for _, c in top10_countries.items()])

# Year bar chart data
year_bar_labels = json.dumps(["2024", "2025", "2026"])
year_bar_counts = json.dumps([yearly_data[y]["count"] for y in [2024, 2025, 2026]])
year_bar_oa = json.dumps([round(yearly_data[y]["oa_rate"], 1) for y in [2024, 2025, 2026]])
year_bar_auth = json.dumps([round(yearly_data[y]["median_authors"], 1) for y in [2024, 2025, 2026]])

# ── Research type trends
rt_trend_names = json.dumps(["Journal Article", "Review", "Case Report", "Systematic Review"])
rt_trend_2024 = json.dumps([type_yearly[rt][2024] for rt in ["Journal Article", "Review", "Case Report", "Systematic Review"]])
rt_trend_2025 = json.dumps([type_yearly[rt][2025] for rt in ["Journal Article", "Review", "Case Report", "Systematic Review"]])
rt_trend_2026 = json.dumps([type_yearly[rt][2026] for rt in ["Journal Article", "Review", "Case Report", "Systematic Review"]])

# Monthly volume by year for comparison
m_labels = json.dumps(["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"])
m2024 = json.dumps([int(monthly_vol_2024.get(m, 0)) for m in range(1, 13)])
m2025 = json.dumps([int(monthly_vol_2025.get(m, 0)) for m in range(1, 13)])
m2026 = json.dumps([int(monthly_vol_2026.get(m, 0)) for m in range(1, 13)])

HTML = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Biomedical Research Landscape 2024–2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #f8f9fa;
    --card-bg: #ffffff;
    --text: #1a1a2e;
    --text-secondary: #495057;
    --accent: #2563eb;
    --accent2: #0891b2;
    --accent3: #7c3aed;
    --border: #dee2e6;
    --positive: #059669;
    --warning: #d97706;
    --kpi-blue: #dbeafe;
    --kpi-green: #d1fae5;
    --kpi-purple: #ede9fe;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }}

  /* ── Header ── */
  .report-header {{
    background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 100%);
    color: #fff;
    padding: 48px 40px;
    text-align: center;
  }}
  .report-header h1 {{
    font-size: 2.2rem;
    font-weight: 700;
    margin-bottom: 8px;
    letter-spacing: -0.5px;
  }}
  .report-header .subtitle {{
    font-size: 1.05rem;
    color: #94a3b8;
    max-width: 720px;
    margin: 0 auto;
    line-height: 1.5;
  }}
  .report-header .meta {{
    margin-top: 16px;
    font-size: 0.85rem;
    color: #64748b;
  }}

  /* ── Container ── */
  .container {{
    max-width: 1100px;
    margin: 0 auto;
    padding: 32px 24px;
  }}

  /* ── KPI Bar ── */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 36px;
  }}
  .kpi-card {{
    background: var(--card-bg);
    border-radius: 10px;
    padding: 20px 24px;
    box-shadow: 0 1px 3px rgba(0,0,0,.08);
    border: 1px solid var(--border);
    text-align: center;
  }}
  .kpi-card .kpi-value {{
    font-size: 2rem;
    font-weight: 700;
    color: var(--text);
  }}
  .kpi-card .kpi-label {{
    font-size: 0.8rem;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-top: 4px;
  }}
  .kpi-card.accent-blue .kpi-value {{ color: var(--accent); }}
  .kpi-card.accent-green .kpi-value {{ color: var(--positive); }}
  .kpi-card.accent-purple .kpi-value {{ color: var(--accent3); }}

  /* ── Sections ── */
  .section {{
    background: var(--card-bg);
    border-radius: 10px;
    padding: 32px;
    margin-bottom: 28px;
    box-shadow: 0 1px 3px rgba(0,0,0,.08);
    border: 1px solid var(--border);
  }}
  .section h2 {{
    font-size: 1.4rem;
    font-weight: 700;
    margin-bottom: 6px;
    color: var(--text);
  }}
  .section .section-obj {{
    font-size: 0.9rem;
    color: var(--text-secondary);
    margin-bottom: 20px;
    font-style: italic;
  }}
  .section h3 {{
    font-size: 1.1rem;
    font-weight: 600;
    margin: 24px 0 12px;
    color: var(--text);
  }}
  .chart-wrapper {{
    position: relative;
    width: 100%;
    margin: 16px 0;
  }}
  .chart-wrapper canvas {{
    width: 100% !important;
    max-height: 380px;
  }}
  .chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }}
  @media (max-width: 768px) {{
    .chart-row {{ grid-template-columns: 1fr; }}
    .report-header h1 {{ font-size: 1.5rem; }}
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
  }}

  /* ── Narrative ── */
  .narrative {{
    font-size: 0.95rem;
    color: var(--text-secondary);
    margin: 12px 0 20px;
  }}
  .narrative p {{ margin-bottom: 10px; }}
  .highlight {{ color: var(--accent); font-weight: 600; }}
  .highlight-green {{ color: var(--positive); font-weight: 600; }}
  .highlight-warn {{ color: var(--warning); font-weight: 600; }}

  /* ── Tables ── */
  .data-table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0;
    font-size: 0.9rem;
  }}
  .data-table th {{
    text-align: left;
    padding: 10px 12px;
