#!/usr/bin/env python3
"""Biomedical Research Landscape 2024–2026 — Analysis & Report Generator"""

import pandas as pd
import numpy as np
import json
import os
from collections import Counter
from io import StringIO
import base64

# ── Load data ──────────────────────────────────────────────────────────
DATA = "/app/benchmark/data.csv"
df = pd.read_csv(DATA, dtype=str, keep_default_na=False)
print(f"Loaded {len(df)} records, {len(df.columns)} columns")

# Convert numeric columns
df["pub_year"] = pd.to_numeric(df["pub_year"], errors="coerce")
df["pub_month_num"] = pd.to_numeric(df["pub_month_num"], errors="coerce")
df["authors_count"] = pd.to_numeric(df["authors_count"], errors="coerce")
df["open_access"] = df["open_access"].map({"True": True, "False": False})

# ── Compute KPIs ───────────────────────────────────────────────────────

# KPI 1: Total Publications by year
year_counts = df["pub_year"].value_counts().sort_index()
total_pubs = len(df)
print(f"\n=== Total Publications: {total_pubs} ===")
for yr, cnt in year_counts.items():
    print(f"  {yr}: {cnt} ({100*cnt/total_pubs:.1f}%)")

# KPI 2: Open Access Rate over time
oa_rate = df["open_access"].mean() * 100
print(f"\nOpen Access Rate: {oa_rate:.1f}%")

# Monthly OA rate
df["year_month"] = df.apply(lambda r: f"{int(r['pub_year'])}-{int(r['pub_month_num']):02d}"
                            if r["pub_month_num"] > 0 else f"{int(r['pub_year'])}-Unknown", axis=1)

# Filter only known months for monthly analysis
df_known_month = df[df["pub_month_num"] > 0].copy()

monthly_oa = df_known_month.groupby("year_month").agg(
    total=("open_access", "count"),
    oa_count=("open_access", "sum"),
    oa_rate=("open_access", "mean")
).reset_index()
monthly_oa["oa_rate_pct"] = monthly_oa["oa_rate"] * 100

# KPI 3: Median authors
median_authors = df["authors_count"].median()
print(f"\nMedian Authors per Publication: {median_authors}")

median_authors_by_year = df.groupby("pub_year")["authors_count"].median()
print(f"Median authors by year: {median_authors_by_year.to_dict()}")

# KPI 4: Top 10 Countries Share
country_counts = df["country"].value_counts()
top10_countries = country_counts.head(10)
top10_share = top10_countries.sum() / total_pubs * 100
print(f"\nTop 10 Countries Share: {top10_share:.1f}%")
for c, cnt in top10_countries.items():
    print(f"  {c}: {cnt} ({100*cnt/total_pubs:.1f}%)")

# KPI 5: Emerging Topic Growth Rate (month-over-month for major_topic)
# First, aggregate major topics by month
topic_monthly = df_known_month.groupby(["major_topic", "year_month"]).size().reset_index(name="count")
topic_monthly = topic_monthly[topic_monthly["major_topic"] != ""]

# Get top topics by total volume
top_topics = df[df["major_topic"] != ""]["major_topic"].value_counts().head(20)
print(f"\n=== Top 20 Major Topics ===")
for t, cnt in top_topics.items():
    print(f"  {t}: {cnt}")

# Compute month-over-month growth for top topics
def compute_mom_growth(topic_df):
    """Compute average MoM growth rate for a topic"""
    topic_df = topic_df.sort_values("year_month")
    if len(topic_df) < 2:
        return 0
    growth_rates = []
    for i in range(1, len(topic_df)):
        prev = topic_df.iloc[i-1]["count"]
        curr = topic_df.iloc[i]["count"]
        if prev > 0:
            growth_rates.append((curr - prev) / prev * 100)
    return np.mean(growth_rates) if growth_rates else 0

topic_growth = {}
