#!/usr/bin/env python3
"""Biomedical Research Landscape 2024–2026 — Analysis & Report Generator"""

import pandas as pd
import numpy as np
import json
import os
from collections import Counter
from io import StringIO
import base64

# ── Load data ──────────────────────────────────────────────────────────
DATA = "/app/benchmark/data.csv"
df = pd.read_csv(DATA, dtype=str, keep_default_na=False)
print(f"Loaded {len(df)} records, {len(df.columns)} columns")

# Convert numeric columns
df["pub_year"] = pd.to_numeric(df["pub_year"], errors="coerce")
df["pub_month_num"] = pd.to_numeric(df["pub_month_num"], errors="coerce")
df["authors_count"] = pd.to_numeric(df["authors_count"], errors="coerce")
df["open_access"] = df["open_access"].map({"True": True, "False": False})

# ── Compute KPIs ───────────────────────────────────────────────────────

# KPI 1: Total Publications by year
year_counts = df["pub_year"].value_counts().sort_index()
total_pubs = len(df)
print(f"\n=== Total Publications: {total_pubs} ===")
for yr, cnt in year_counts.items():
    print(f"  {yr}: {cnt} ({100*cnt/total_pubs:.1f}%)")

# KPI 2: Open Access Rate over time
oa_rate = df["open_access"].mean() * 100
print(f"\nOpen Access Rate: {oa_rate:.1f}%")

# Monthly OA rate
df["year_month"] = df.apply(lambda r: f"{int(r['pub_year'])}-{int(r['pub_month_num']):02d}"
                            if r["pub_month_num"] > 0 else f"{int(r['pub_year'])}-Unknown", axis=1)

# Filter only known months for monthly analysis
df_known_month = df[df["pub_month_num"] > 0].copy()

monthly_oa = df_known_month.groupby("year_month").agg(
    total=("open_access", "count"),
    oa_count=("open_access", "sum"),
    oa_rate=("open_access", "mean")
).reset_index()
monthly_oa["oa_rate_pct"] = monthly_oa["oa_rate"] * 100

# KPI 3: Median authors
median_authors = df["authors_count"].median()
print(f"\nMedian Authors per Publication: {median_authors}")

median_authors_by_year = df.groupby("pub_year")["authors_count"].median()
print(f"Median authors by year: {median_authors_by_year.to_dict()}")

# KPI 4: Top 10 Countries Share
country_counts = df["country"].value_counts()
top10_countries = country_counts.head(10)
top10_share = top10_countries.sum() / total_pubs * 100
print(f"\nTop 10 Countries Share: {top10_share:.1f}%")
for c, cnt in top10_countries.items():
    print(f"  {c}: {cnt} ({100*cnt/total_pubs:.1f}%)")

# KPI 5: Emerging Topic Growth Rate (month-over-month for major_topic)
# First, aggregate major topics by month
topic_monthly = df_known_month.groupby(["major_topic", "year_month"]).size().reset_index(name="count")
topic_monthly = topic_monthly[topic_monthly["major_topic"] != ""]

# Get top topics by total volume
top_topics = df[df["major_topic"] != ""]["major_topic"].value_counts().head(20)
print(f"\n=== Top 20 Major Topics ===")
for t, cnt in top_topics.items():
    print(f"  {t}: {cnt}")

# Compute month-over-month growth for top topics
def compute_mom_growth(topic_df):
    """Compute average MoM growth rate for a topic"""
    topic_df = topic_df.sort_values("year_month")
    if len(topic_df) < 2:
        return 0
    growth_rates = []
    for i in range(1, len(topic_df)):
        prev = topic_df.iloc[i-1]["count"]
        curr = topic_df.iloc[i]["count"]
        if prev > 0:
            growth_rates.append((curr - prev) / prev * 100)
    return np.mean(growth_rates) if growth_rates else 0

topic_growth = {}
for topic in top_topics.index[:20]:
    tdf = topic_monthly[topic_monthly["major_topic"] == topic]
    growth = compute_mom_growth(tdf)
    topic_growth[topic] = growth

# Sort by growth rate
sorted_growth = sorted(topic_growth.items(), key=lambda x: x[1], reverse=True)
print(f"\n=== Topic Growth Rates (avg MoM %) ===")
for t, g in sorted_growth:
    print(f"  {t}: {g:+.1f}%")

# ── Additional Analysis ────────────────────────────────────────────────

# Monthly publication volume
monthly_pubs = df_known_month.groupby("year_month").size().reset_index(name="count")

# Research type distribution
# split multi-value research_type
all_types = []
for rt in df["research_type"]:
    types = [t.strip() for t in rt.split(";")]
    all_types.extend(types)
research_type_counts = Counter(all_types)
print(f"\n=== Research Types ===")
for rt, cnt in research_type_counts.most_common():
    print(f"  {rt}: {cnt}")

# Authors per country
country_median_authors = df.groupby("country")["authors_count"].median()
# top 15 by volume, get median authors
top15_countries = country_counts.head(15).index
country_author_data = {c: df[df["country"]==c]["authors_count"].median() for c in top15_countries}

# OA by country (top 15)
country_oa = {}
for c in top15_countries:
    cdf = df[df["country"] == c]
    country_oa[c] = cdf["open_access"].mean() * 100

# OA by research type
oa_by_type = {}
for rt in ["Journal Article", "Review", "Systematic Review", "Case Report"]:
    mask = df["research_type"].str.contains(rt, na=False)
    oa_by_type[rt] = df[mask]["open_access"].mean() * 100

# Research type over time
type_yearly = {}
for rt in ["Journal Article", "Review", "Case Report", "Systematic Review"]:
    type_yearly[rt] = {}
    for yr in [2024, 2025, 2026]:
        yr_mask = (df["pub_year"] == yr) & df["research_type"].str.contains(rt, na=False)
        type_yearly[rt][yr] = yr_mask.sum()

# Yearly summary
yearly_data = {}
for yr in [2024, 2025, 2026]:
    yr_df = df[df["pub_year"] == yr]
    yearly_data[yr] = {
        "count": len(yr_df),
        "oa_rate": yr_df["open_access"].mean() * 100,
        "median_authors": yr_df["authors_count"].median(),
        "pct_total": len(yr_df) / total_pubs * 100
    }

# Monthly volume by year
monthly_vol_2024 = df_known_month[df_known_month["pub_year"] == 2024].groupby("pub_month_num").size()
monthly_vol_2025 = df_known_month[df_known_month["pub_year"] == 2025].groupby("pub_month_num").size()
monthly_vol_2026 = df_known_month[df_known_month["pub_year"] == 2026].groupby("pub_month_num").size()

# ── Save analysis results ──────────────────────────────────────────────
analysis = {
    "total_pubs": total_pubs,
    "year_counts": {int(k): int(v) for k, v in year_counts.items()},
    "oa_rate": round(oa_rate, 1),
    "median_authors": float(median_authors),
    "top10_share": round(top10_share, 1),
    "top10_countries": [(str(c), int(cnt)) for c, cnt in top10_countries.items()],
    "top_topics": [(str(t), int(cnt)) for t, cnt in top_topics.head(20).items()],
    "topic_growth": {str(k): round(v, 1) for k, v in sorted_growth[:15]},
    "research_types": research_type_counts.most_common(),
    "yearly_data": {int(k): v for k, v in yearly_data.items()},
    "oa_by_type": {k: round(v, 1) for k, v in oa_by_type.items()},
    "country_oa": {str(k): round(v, 1) for k, v in country_oa.items()},
    "country_median_authors": {str(k): round(v, 1) for k, v in country_author_data.items()},
}

with open("/app/output/analysis.json", "w") as f:
    json.dump(analysis, f, indent=2)
print("\nAnalysis saved to /app/output/analysis.json")

# ── Prepare data series for charts ─────────────────────────────────────
# Monthly volume series
months_order = []
for yr in [2024, 2025, 2026]:
    for m in range(1, 13):
        months_order.append(f"{yr}-{m:02d}")

monthly_series = [int(monthly_pubs[monthly_pubs["year_month"]==m]["count"].values[0])
                  if m in monthly_pubs["year_month"].values else 0
                  for m in months_order]

monthly_oa_series = [float(monthly_oa[monthly_oa["year_month"]==m]["oa_rate_pct"].values[0])
                     if m in monthly_oa["year_month"].values else None
                     for m in months_order]

# Write monthly data for chart JS
monthly_labels = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
chart_data = {
