    "country_median_authors": {str(k): round(v, 1) for k, v in country_author_data.items()},
}

with open("/app/output/analysis.json", "w") as f:
    json.dump(analysis, f, indent=2)
print("\nAnalysis saved to /app/output/analysis.json")

# ── Prepare data series for charts ─────────────────────────────────────
# Monthly volume series
months_order = []
for yr in [2024, 2025, 2026]:
    for m in range(1, 13):
        months_order.append(f"{yr}-{m:02d}")

monthly_series = [int(monthly_pubs[monthly_pubs["year_month"]==m]["count"].values[0])
                  if m in monthly_pubs["year_month"].values else 0
