      <tr><td>2025</td><td>{fmt(yearly_data[2025]['count'])}</td><td>{pct(yearly_data[2025]['pct_total'])}</td><td>{pct(yearly_data[2025]['oa_rate'])}</td><td>{yearly_data[2025]['median_authors']:.0f}</td></tr>
      <tr><td>2026</td><td>{fmt(yearly_data[2026]['count'])}</td><td>{pct(yearly_data[2026]['pct_total'])}</td><td>{pct(yearly_data[2026]['oa_rate'])}</td><td>{yearly_data[2026]['median_authors']:.0f}</td></tr>
    </tbody>
  </table>
</div>

<!-- ═══════════════ SECTION 2: GEOGRAPHIC LANDSCAPE ═══════════════ -->
<div class="section" id="geographic-landscape">
  <h2>Geographic Landscape of Biomedical Research</h2>
  <p class="section-obj">Top contributing countries by publication count, geographic contribution shifts across 2024–2026.</p>

  <div class="chart-row">
    <div class="chart-wrapper">
      <canvas id="chartCountries"></canvas>
    </div>
    <div class="chart-wrapper">
      <canvas id="chartCountryOA"></canvas>
    </div>
  </div>

