    HTML += f"<tr><td>{rt}</td><td>{fmt(cnt)}</td><td>{pct(share)}</td><td>{pct(oa)}</td></tr>\n"

HTML += """
    </tbody>
  </table>
</div>

<!-- ═══════════════ SECTION 6: KEY TAKEAWAYS ═══════════════ -->
<div class="section" id="key-takeaways">
  <h2>Key Takeaways &amp; Strategic Implications</h2>

"""
# Build priority-ranked takeaways

HTML += f"""
